BONE_MAPPING = {
    'eye_L': 'eye.L',
    'eye_R': 'eye.R',
    # Add other mappings if needed
}

def get_mapped_name(name):
    return BONE_MAPPING.get(name, name)

def get_isaac_actions():
    isaac = bpy.data.objects.get("isaac FaceRig")
    actions_map = {}
    if isaac and isaac.animation_data:
        for track in isaac.animation_data.nla_tracks:
            for strip in track.strips:
                if strip.action:
                    # Map strip name to action
                    actions_map[strip.name] = strip.action
                    # Also map action name just in case
                    actions_map[strip.action.name] = strip.action
                    # Map base name (e.g. m7eyetop from m7eyetop.001)
                    base_name = strip.name.split('.')[0]
                    if base_name not in actions_map:
                         actions_map[base_name] = strip.action
    return actions_map

def setup_face_rig(target_rig_name=None):
    if target_rig_name:
        target_rig = bpy.data.objects.get(target_rig_name)
    else:
        target_rig = bpy.context.active_object
        
    if not target_rig or target_rig.type != 'ARMATURE':
        print(f"Error: Target rig not found or not an armature. Active: {bpy.context.active_object}")
        return

    print(f"Setting up face rig on: {target_rig.name}")

    bpy.context.view_layer.objects.active = target_rig
    # Ensure mode is object before switching
    if bpy.context.object and bpy.context.object.mode != 'OBJECT':
         bpy.ops.object.mode_set(mode='OBJECT')
         
    bpy.ops.object.mode_set(mode='EDIT')
    
    eb = target_rig.data.edit_bones
    
    # Locate Anchor
    anchor_name = "DEF-spine.006"
    anchor_matrix = Matrix.Identity(4)
    if anchor_name in eb:
        anchor_matrix = eb[anchor_name].matrix
    else:
        # Fallback to head if exists
        targets = ["head", "Head"]
        for t in targets:
             if t in eb:
                 anchor_name = t
                 anchor_matrix = eb[t].matrix
                 print(f"DEF-spine.006 not found, using '{t}' as anchor")
                 break
        else:
             print(f"Warning: Anchor '{anchor_name}' not found in target. Using World Origin.")
    
    # 1. Create/Update Bones
    for b_data in RIG_DATA['bones']:
        name = get_mapped_name(b_data['name'])
        
        if name in eb:
            # Bone exists on target character.
            # We assume existing bones are correct, but we might want to ensure they are connected if we are building hierarchy.
            continue
            
        # New Bone -> Create relative to anchor
        new_bone = eb.new(name)
        
        rel_head = Vector(b_data['rel_head'])
        rel_tail = Vector(b_data['rel_tail'])
        
        # Apply target anchor transform
        new_bone.head = anchor_matrix @ rel_head
        new_bone.tail = anchor_matrix @ rel_tail
        new_bone.roll = b_data['roll']
        new_bone.use_connect = b_data['use_connect']

    # Parents
    for b_data in RIG_DATA['bones']:
        name = get_mapped_name(b_data['name'])
        if b_data['parent']:
            parent_name = get_mapped_name(b_data['parent'])
            
            if parent_name in eb and name in eb:
                # Only reparent if the bone was created by us OR if we want to enforce hierarchy on existing bones.
                # Enforcing strictly might break existing rig, so let's be careful.
                # Current logic: If child has NO parent, or if we created it, assign parent.
                # Actually, better to just enforce it if it's part of our face rig logic.
                # Enforce parenting defined in RIG_DATA
                if eb[name].parent != eb[parent_name]:
                     # print(f"Reparenting {name} from {eb[name].parent.name if eb[name].parent else 'None'} to {parent_name}")
                     eb[name].parent = eb[parent_name]
                # If it already has a parent, maybe check if it matches? 
                # For safety, let's overlap: if parent is different and we created this bone, switch.
                # If existing bone, leave it (might be parented to something else).

    bpy.ops.object.mode_set(mode='OBJECT')
    
    # 2. Collections
    if hasattr(target_rig.data, "collections"):
        for c_data in RIG_DATA['collections']:
            coll = target_rig.data.collections.get(c_data['name'])
            if not coll:
                coll = target_rig.data.collections.new(c_data['name'])
            
            for b_name in c_data['bones']:
                mapped_name = get_mapped_name(b_name)
                bone = target_rig.data.bones.get(mapped_name)
                if bone:
                    coll.assign(bone)

    # 3. Recreate Actions
    if 'actions' in RIG_DATA:
        for a_name, a_data in RIG_DATA['actions'].items():
            # Strip .001, .002 etc suffixes
            clean_name = re.sub(r'\.\d+$', '', a_name)
            
            if clean_name not in bpy.data.actions:
                act = bpy.data.actions.new(clean_name)
            else:
                act = bpy.data.actions[clean_name]
            
            # Ensure name is enforcing cleaned version
            if act.name != clean_name:
                act.name = clean_name
            
            # Ensure ID Root is OBJECT
            if not act.id_root:
                if not target_rig.animation_data:
                    target_rig.animation_data_create()
                prev_act = target_rig.animation_data.action
                target_rig.animation_data.action = act
                target_rig.animation_data.action = prev_act
            
            # Clear existing curves
            for fc in act.fcurves:
                 act.fcurves.remove(fc)
                 
            for c_data in a_data['curves']:
                path = c_data['data_path']
                # Remap path if needed
                for s, t in BONE_MAPPING.items():
                    path = path.replace(f'["{s}"]', f'["{t}"]')
                    
                fc = act.fcurves.new(path, index=c_data['array_index'])
                fc.keyframe_points.add(len(c_data['keyframes']))
                
                for k, k_data in enumerate(c_data['keyframes']):
                    kp = fc.keyframe_points[k]
                    kp.co = k_data['co']
                    kp.interpolation = k_data['interpolation']
                    if 'handle_left' in k_data:
                        kp.handle_left = k_data['handle_left']
                        kp.handle_right = k_data['handle_right']

    # 4. Custom Props & Constraints (With Actions linked)
    for prop in RIG_DATA['custom_props']:
        name = get_mapped_name(prop['bone'])
        pb = target_rig.pose.bones.get(name)
        if pb:
            try:
                pb[prop['key']] = prop['value']
            except:
                pass
            
    for const in RIG_DATA['constraints']:
        name = get_mapped_name(const['bone'])
        pb = target_rig.pose.bones.get(name)
        if not pb: continue
        
        is_new_constraint = False
        c = next((x for x in pb.constraints if x.name == const['name']), None)
        if not c:
            c = pb.constraints.new(const['type'])
            c.name = const['name']
            is_new_constraint = True
            
        c.influence = const['influence']
        
        target_name = const.get('target')
        real_target = None
        if target_name:
             if target_name == "isaac FaceRig": 
                 real_target = target_rig
             else:
                 real_target = bpy.data.objects.get(target_name)
        
        # User requested NOT to reset Bone of Copy Transforms if it exists
        should_update_target = True
        if c.type == 'COPY_TRANSFORMS' and not is_new_constraint:
            # If it's an existing COPY_TRANSFORMS, do not touch target/subtarget
            should_update_target = False
            
        if should_update_target:
            if hasattr(c, 'target') and real_target:
                c.target = real_target
            if hasattr(c, 'subtarget') and const['subtarget']:
                c.subtarget = get_mapped_name(const['subtarget'])
            
        for k, v in const.items():
            if k not in ['bone', 'name', 'type', 'target', 'subtarget', 'influence']:
                if k == 'action_name' and v:
                     # Link Action
                     clean_v = re.sub(r'\.\d+$', '', v)
                     
                     # Try finding in Isaac first
                     isaac_actions = get_isaac_actions() 
                     
                     # Try exact match, then clean match in Isaac
                     act = isaac_actions.get(v)
                     if not act:
                         act = isaac_actions.get(clean_v)
                         
                     if not act:
                        act = bpy.data.actions.get(clean_v)
                        if not act:
                            act = bpy.data.actions.get(v)

                     if act:
                         c.action = act
                     else:
                         print(f"Warning: Action '{v}' not found for constraint {c.name} on bone {pb.name}")
                elif hasattr(c, k):
                    try:
                        setattr(c, k, v)
                    except:
                        pass
    
    # 5. Drivers
    for dr_data in RIG_DATA['drivers']:
        d_obj = target_rig
        idx = dr_data['array_index']
        path = dr_data['data_path']
        # Remap path
        for s, t in BONE_MAPPING.items():
            path = path.replace(f'["{s}"]', f'["{t}"]')
            
        try:
            d = d_obj.driver_add(path, idx).driver
            d.type = dr_data['type']
            d.expression = dr_data['expression']
        except Exception as e:
            # print(f"Warning: Failed to add driver for {path} at index {idx}: {e}")
            continue
        
        for v_data in dr_data['variables']:
            var = d.variables.new()
            var.name = v_data['name']
            var.type = v_data['type']
            
            for i, t_data in enumerate(v_data['targets']):
                tar = var.targets[i]
                tar.id_type = t_data['id_type']
                
                if t_data.get('id_self'):
                    tar.id = target_rig
                elif t_data.get('id_name'):
                    if t_data['id_name'] == "isaac FaceRig":
                        tar.id = target_rig
                    else:
                        tar.id = bpy.data.objects.get(t_data['id_name'])
                
                if t_data['bone_target']:
                    tar.bone_target = get_mapped_name(t_data['bone_target'])
                if t_data['data_path']:
                    # Remap target data path too if it refers to a bone
                    dpath = t_data['data_path']
                    for s, t in BONE_MAPPING.items():
                        dpath = dpath.replace(f'["{s}"]', f'["{t}"]')
                    tar.data_path = dpath
                if t_data['transform_type']:
                    tar.transform_type = t_data['transform_type']
                if t_data['transform_space']:
                    tar.transform_space = t_data['transform_space']

    # 6. Custom Shapes
    # Logic: 
    # 1. Find or Create a suitable widget collection (prefer existing WGTS_*)
    # 2. Create shapes with 'WGT-Face_' prefix to avoid generic 'Plane.xxx' names
    
    wgt_coll = None
    # Try to find existing WGTS collection
    for c in bpy.data.collections:
        if "WGTS" in c.name:
            wgt_coll = c
            break
            
    if not wgt_coll:
        wgt_coll_name = f"WGTS_{target_rig.name}"
        wgt_coll = bpy.data.collections.get(wgt_coll_name)
        if not wgt_coll:
             wgt_coll = bpy.data.collections.new(wgt_coll_name)
             bpy.context.scene.collection.children.link(wgt_coll)
    
    created_shapes = {}
    if 'custom_shapes' in RIG_DATA:
        for s_name, s_data in RIG_DATA['custom_shapes'].items():
            # Use a better name
            new_name = f"WGT-Face_{s_name}"
            
            # Check if exists
            obj = bpy.data.objects.get(new_name)
            
            if not obj:
                # Fallback: check original name?
                obj = bpy.data.objects.get(s_name)
            
            if not obj:
                # Create it
                mesh = bpy.data.meshes.new(new_name)
                mesh.from_pydata(s_data['verts'], s_data['edges'], s_data.get('faces', []))
                obj = bpy.data.objects.new(new_name, mesh)
                wgt_coll.objects.link(obj)
            
            created_shapes[s_name] = obj
            
    if 'bone_shapes' in RIG_DATA:
        for shape_info in RIG_DATA['bone_shapes']:
            name = get_mapped_name(shape_info['bone'])
            pb = target_rig.pose.bones.get(name)
            
            # Look up using original name key
            shape_obj = created_shapes.get(shape_info['shape'])
            
            if pb and shape_obj:
                pb.custom_shape = shape_obj
                pb.custom_shape_scale_xyz = Vector(shape_info['scale'])
                pb.custom_shape_translation = Vector(shape_info['translation'])

                pb.custom_shape_rotation_euler = Vector(shape_info['rotation'])

    # 7. Dynamic Eyebrow Adjustment
    # Calculate bounds of Inn/Mid/Out and fit Master shape
    for side, suffix in [('R', 'R'), ('L', 'L')]:
        master_name = get_mapped_name(f'Eyebrow-Master.{suffix}')
        inn_name = get_mapped_name(f'eyebrow_Inn_{suffix}.001')
        out_name = get_mapped_name(f'eyebrow_Out_{suffix}.001')
        
        master_pb = target_rig.pose.bones.get(master_name)
        master_bone = target_rig.data.bones.get(master_name)
        inn_bone = target_rig.data.bones.get(inn_name)
        out_bone = target_rig.data.bones.get(out_name)
        
        if master_pb and master_bone and inn_bone and out_bone:
            # Transform to Master Local Space
            mat_inv = master_bone.matrix_local.inverted()
            inn_loc = mat_inv @ inn_bone.head_local
            out_loc = mat_inv @ out_bone.head_local
            
            # Determine Min/Max X
            # Note: Depending on bone roll, X might be inverted.
            # We want the shape to span from Out to Inn.
            
            # Center
            center_x = (inn_loc.x + out_loc.x) / 2.0
            width = abs(inn_loc.x - out_loc.x)
            
            # Apply Layout
            # Preserve Y/Z scale (thickness)
            current_scale = master_pb.custom_shape_scale_xyz
            
            # Estimate Scale Factor: 
            # Assuming Shape Plane.001 is approx 0.12 units wide naturally?
            # We use a factor (e.g. 8.0) that seemed roughly correct in magnitude (0.03 * 8 = 0.24 ~ 0.25)
            scale_x = width * 8.0 
            
            # For Left side, we might need to flip if mirroring is desired
            if side == 'L':
                 scale_x *= -1
            
            master_pb.custom_shape_translation.x = center_x
            master_pb.custom_shape_scale_xyz.x = scale_x
            
            # Reset Y/Z translation just in case
            master_pb.custom_shape_translation.y = 0
            master_pb.custom_shape_translation.z = 0

            print(f"Adjusted {master_name}: CenterX={center_x:.4f}, Width={width:.4f}, ScaleX={scale_x:.4f}")


    print("Face Rig Setup Complete on", target_rig.name)

if __name__ == "__main__":
    setup_face_rig()